actions.apply:
$exe = Join-Path $env:SystemRoot 'System32\powercfg.exe'
$null = & $exe /hibernate off 2>&1
if ($LASTEXITCODE -ne 0) { throw ('powercfg /hibernate off failed with exit code ' + $LASTEXITCODE) }

actions.revert:
$exe = Join-Path $env:SystemRoot 'System32\powercfg.exe'
$null = & $exe /hibernate on 2>&1
if ($LASTEXITCODE -ne 0) { throw ('powercfg /hibernate on failed with exit code ' + $LASTEXITCODE) }

actions.detect:
try {
  $base = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, [Microsoft.Win32.RegistryView]::Registry64)
  $k = $base.OpenSubKey('SYSTEM\CurrentControlSet\Control\Power')
  if ($null -eq $k) { return $null }
  $v = $k.GetValue('HibernateEnabled', $null)
  if ($null -eq $v) { $v = $k.GetValue('HibernateEnabledDefault', $null) }
  $k.Close()
  if ($null -eq $v) { return $null }
  return ([int]$v -eq 0)
} catch {
  return $null
}
